const input = $input.first().json || {};
const body = input.body && typeof input.body === 'object' && !Array.isArray(input.body) ? input.body : input;
const errors = [];
const safe = body && typeof body === 'object' && !Array.isArray(body) ? body : {};

if (body === null || typeof body !== 'object' || Array.isArray(body)) {
  errors.push({ field: 'body', message: 'Le corps doit etre un objet JSON.' });
}

const allowed = ['daty', 'anneebudgetaire', 'designation', 'typebordereau'];
for (const key of Object.keys(safe)) {
  if (!allowed.includes(key)) errors.push({ field: key, message: 'Champ non autorise.' });
}

const isText = (value) => typeof value === 'string' && value.trim().length > 0;
const isDaty = (value) => {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(value + 'T00:00:00Z');
  return !isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
};
const isYear = (value) => {
  if (typeof value === 'number') return Number.isInteger(value) && value > 0;
  if (typeof value === 'string' && /^[0-9]+$/.test(value.trim())) return parseInt(value.trim(), 10) > 0;
  return false;
};
const isType = (value) => typeof value === 'string' && /^TYPB[12]$/i.test(value.trim());

if (!isDaty(safe.daty)) errors.push({ field: 'daty', message: 'Date requise au format AAAA-MM-JJ.' });
if (!isYear(safe.anneebudgetaire)) errors.push({ field: 'anneebudgetaire', message: 'Annee budgetaire strictement positive requise.' });
if (!isText(safe.designation)) errors.push({ field: 'designation', message: 'Valeur texte non vide requise.' });
else if (safe.designation.trim().length > 40) errors.push({ field: 'designation', message: '40 caracteres maximum.' });
if (!isType(safe.typebordereau)) errors.push({ field: 'typebordereau', message: 'Valeur attendue : TYPB1 (BED) ou TYPB2 (Etat de depense).' });

return [{ json: { ok: errors.length === 0, errors } }];
